import pandas as pd, numpy as np

df = pd.read_csv('benchmark/data.csv')
name = df['OBJECT_NAME'].astype(str)
# Better prefix: take leading alphabetic chunk, else first token
# Use regex to capture leading letters (and maybe digits for GPS?)
import re

def prefixify(s):
    m = re.match(r'^([A-Z]+)', s)
    if m:
        return m.group(1)
    m = re.match(r'^([0-9]{4})', s)
    if m:
        return m.group(1)
    return s.split(' ')[0].split('-')[0]

pref = name.str.upper().map(prefixify)
vc = pref.value_counts().head(25)
print(vc)
PY"}

